content:
Below is a reusable Terraform module implementing the requested S3, RDS PostgreSQL, and IAM service-account role resources. Production additionally enables cross-region S3 replication to `us-west-2`.

## Directory layout

```text
terraform/
├── modules/
│   └── application-data/
│       ├── main.tf
│       ├── variables.tf
│       ├── outputs.tf
│       └── versions.tf
├── main.tf
├── variables.tf
├── outputs.tf
├── versions.tf
├── dev.tfvars
└── prod.tfvars
```

---

## `modules/application-data/versions.tf`

```hcl
terraform {
  required_version = ">= 1.6.0"

  required_providers {
    aws = {
      source                = "hashicorp/aws"
      version               = ">= 5.92.0"
      configuration_aliases = [aws.replica]
    }
  }
}
```

## `modules/application-data/variables.tf`

```hcl
variable "name" {
  description = "Base name used for resources."
  type        = string
}

variable "environment" {
  description = "Deployment environment."
  type        = string

  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "environment must be dev or prod."
  }
}

variable "tags" {
  description = "Additional resource tags."
  type        = map(string)
  default     = {}
}

variable "vpc_id" {
  description = "VPC in which the RDS instance is deployed."
  type        = string
}

variable "database_subnet_ids" {
  description = "Private subnet IDs for the RDS subnet group."
  type        = list(string)

  validation {
    condition     = length(var.database_subnet_ids) >= 2
    error_message = "At least two database subnet IDs are required."
  }
}

variable "application_security_group_id" {
  description = "Security group allowed to connect to PostgreSQL."
  type        = string
}

variable "db_instance_class" {
  description = "RDS instance class."
  type        = string
}

variable "db_allocated_storage" {
  description = "Initial RDS storage in GiB."
  type        = number
  default     = 20
}

variable "db_max_allocated_storage" {
  description = "Maximum storage autoscaling limit in GiB."
  type        = number
  default     = 100
}

variable "db_name" {
  description = "Initial PostgreSQL database name."
  type        = string
  default     = "application"
}

variable "db_username" {
  description = "PostgreSQL master username."
  type        = string
  default     = "appadmin"
}

variable "db_password" {
  description = "PostgreSQL master password. Supply through TF_VAR_db_password or an encrypted var file; never commit it."
  type        = string
  sensitive   = true
  ephemeral   = true
}

variable "db_password_version" {
  description = "Increment this value whenever db_password is rotated."
  type        = number
  default     = 1
}

variable "db_multi_az" {
  description = "Whether RDS is deployed in multiple availability zones."
  type        = bool
}

variable "db_storage_encrypted" {
  description = "Whether RDS storage encryption is enabled."
  type        = bool
  default     = true
}

variable "db_kms_key_id" {
  description = "Optional KMS key ARN for RDS encryption. AWS-managed encryption is used when null."
  type        = string
  default     = null
}

variable "db_backup_retention_period" {
  description = "Number of days for automated backups."
  type        = number
  default     = 7

  validation {
    condition     = var.db_backup_retention_period >= 7
    error_message = "RDS backup retention must be at least 7 days."
  }
}

variable "oidc_provider_arn" {
  description = "ARN of the EKS OIDC provider."
  type        = string
}

variable "oidc_issuer_url" {
  description = "EKS OIDC issuer URL, with or without the https:// prefix."
  type        = string
}

variable "service_account_namespace" {
  description = "Kubernetes namespace containing the service account."
  type        = string
}

variable "service_account_name" {
  description = "Kubernetes service account name."
  type        = string
}

variable "enable_replication" {
  description = "Create a replica bucket and replicate objects to us-west-2."
  type        = bool
  default     = false
}
```

## `modules/application-data/main.tf`

```hcl
locals {
  resource_name = "${var.name}-${var.environment}"

  common_tags = merge(var.tags, {
    Application = var.name
    Environment = var.environment
    ManagedBy   = "Terraform"
  })

  oidc_issuer = trimsuffix(
    trimprefix(var.oidc_issuer_url, "https://"),
    "/"
  )
}

# ------------------------------------------------------------------------------
# Primary S3 bucket
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "assets" {
  bucket = "${local.resource_name}-assets"

  tags = merge(local.common_tags, {
    Name = "${local.resource_name}-assets"
  })
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket = aws_s3_bucket.assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "assets" {
  bucket = aws_s3_bucket.assets.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_policy" "assets_tls_only" {
  bucket = aws_s3_bucket.assets.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid       = "DenyInsecureTransport"
      Effect    = "Deny"
      Principal = "*"
      Action    = "s3:*"
      Resource = [
        aws_s3_bucket.assets.arn,
        "${aws_s3_bucket.assets.arn}/*"
      ]
      Condition = {
        Bool = {
          "aws:SecureTransport" = "false"
        }
      }
    }]
  })

  depends_on = [aws_s3_bucket_public_access_block.assets]
}

# ------------------------------------------------------------------------------
# Production cross-region replica bucket
# Uses the root module's aws.replica provider, configured for us-west-2.
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica

  bucket = "${local.resource_name}-assets-replica"

  tags = merge(local.common_tags, {
    Name    = "${local.resource_name}-assets-replica"
    Purpose = "Cross-region replication destination"
  })
}

resource "aws_s3_bucket_versioning" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_policy" "replica_tls_only" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid       = "DenyInsecureTransport"
      Effect    = "Deny"
      Principal = "*"
      Action    = "s3:*"
      Resource = [
        aws_s3_bucket.replica[0].arn,
        "${aws_s3_bucket.replica[0].arn}/*"
      ]
      Condition = {
        Bool = {
          "aws:SecureTransport" = "false"
        }
      }
    }]
  })

  depends_on = [aws_s3_bucket_public_access_block.replica]
}

# ------------------------------------------------------------------------------
# S3 replication IAM role
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "replication_assume_role" {
  count = var.enable_replication ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  count = var.enable_replication ? 1 : 0

  name               = "${local.resource_name}-s3-replication"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role[0].json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "replication" {
  count = var.enable_replication ? 1 : 0

  statement {
    sid = "ReadSourceBucket"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket"
    ]

    resources = [aws_s3_bucket.assets.arn]
  }

  statement {
    sid = "ReadSourceVersions"

    actions = [
      "s3:GetObjectVersion",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionTagging"
    ]

    resources = ["${aws_s3_bucket.assets.arn}/*"]
  }

  statement {
    sid = "ReplicateToDestination"

    actions = [
      "s3:ReplicateDelete",
      "s3:ReplicateObject",
      "s3:ReplicateTags"
    ]

    resources = ["${aws_s3_bucket.replica[0].arn}/*"]
  }
}

resource "aws_iam_role_policy" "replication" {
  count = var.enable_replication ? 1 : 0

  name   = "${local.resource_name}-s3-replication"
  role   = aws_iam_role.replication[0].id
  policy = data.aws_iam_policy_document.replication[0].json
}

resource "aws_s3_bucket_replication_configuration" "assets" {
  count = var.enable_replication ? 1 : 0

  bucket = aws_s3_bucket.assets.id
  role   = aws_iam_role.replication[0].arn

  rule {
    id     = "replicate-all"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD"
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.assets,
    aws_s3_bucket_versioning.replica,
    aws_iam_role_policy.replication
  ]
}

# ------------------------------------------------------------------------------
# RDS PostgreSQL
# ------------------------------------------------------------------------------

resource "aws_db_subnet_group" "database" {
  name       = "${local.resource_name}-database"
  subnet_ids = var.database_subnet_ids

  tags = merge(local.common_tags, {
    Name = "${local.resource_name}-database"
  })
}

resource "aws_security_group" "database" {
  name_prefix = "${local.resource_name}-database-"
  description = "PostgreSQL access from the application security group"
  vpc_id      = var.vpc_id

  ingress {
    description     = "PostgreSQL from application"
    protocol        = "tcp"
    from_port       = 5432
    to_port         = 5432
    security_groups = [var.application_security_group_id]
  }

  egress {
    description = "Allow response traffic"
    protocol    = "-1"
    from_port   = 0
    to_port     = 0
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.resource_name}-database"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_db_instance" "postgresql" {
  identifier = "${local.resource_name}-postgresql"

  engine         = "postgres"
  engine_version = "16"

  instance_class        = var.db_instance_class
  allocated_storage     = var.db_allocated_storage
  max_allocated_storage = var.db_max_allocated_storage
  storage_type          = "gp3"
  storage_encrypted     = var.db_storage_encrypted
  kms_key_id            = var.db_kms_key_id

  db_name  = var.db_name
  username = var.db_username

  # Write-only argument prevents the password from being persisted in state.
  password_wo         = var.db_password
  password_wo_version = var.db_password_version

  port                   = 5432
  multi_az               = var.db_multi_az
  publicly_accessible    = false
  deletion_protection    = true
  backup_retention_period = var.db_backup_retention_period
  copy_tags_to_snapshot  = true
  auto_minor_version_upgrade = true

  db_subnet_group_name   = aws_db_subnet_group.database.name
  vpc_security_group_ids = [aws_security_group.database.id]

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.resource_name}-postgresql-final"
  apply_immediately          = var.environment == "dev"

  tags = merge(local.common_tags, {
    Name = "${local.resource_name}-postgresql"
  })
}

# ------------------------------------------------------------------------------
# IAM role for Kubernetes service account (IRSA)
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "service_account_assume_role" {
  statement {
    sid     = "AllowEksServiceAccount"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [var.oidc_provider_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.oidc_issuer}:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.oidc_issuer}:sub"
      values = [
        "system:serviceaccount:${var.service_account_namespace}:${var.service_account_name}"
      ]
    }
  }
}

resource "aws_iam_role" "service_account" {
  name               = "${local.resource_name}-service-account"
  assume_role_policy = data.aws_iam_policy_document.service_account_assume_role.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "service_account" {
  statement {
    sid     = "ListApplicationAssets"
    effect  = "Allow"
    actions = ["s3:ListBucket"]
    resources = [
      aws_s3_bucket.assets.arn
    ]
  }

  statement {
    sid    = "ManageApplicationAssets"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject"
    ]

    resources = [
      "${aws_s3_bucket.assets.arn}/*"
    ]
  }
}

resource "aws_iam_role_policy" "service_account" {
  name   = "${local.resource_name}-assets"
  role   = aws_iam_role.service_account.id
  policy = data.aws_iam_policy_document.service_account.json
}
```

## `modules/application-data/outputs.tf`

```hcl
output "assets_bucket_name" {
  description = "Primary assets bucket name."
  value       = aws_s3_bucket.assets.id
}

output "assets_bucket_arn" {
  description = "Primary assets bucket ARN."
  value       = aws_s3_bucket.assets.arn
}

output "replica_bucket_name" {
  description = "Replica bucket name, or null when replication is disabled."
  value       = try(aws_s3_bucket.replica[0].id, null)
}

output "database_endpoint" {
  description = "RDS PostgreSQL endpoint."
  value       = aws_db_instance.postgresql.address
}

output "database_port" {
  description = "RDS PostgreSQL port."
  value       = aws_db_instance.postgresql.port
}

output "database_name" {
  description = "Initial PostgreSQL database name."
  value       = aws_db_instance.postgresql.db_name
}

output "database_security_group_id" {
  description = "RDS security group ID."
  value       = aws_security_group.database.id
}

output "service_account_role_arn" {
  description = "IAM role ARN to annotate on the Kubernetes service account."
  value       = aws_iam_role.service_account.arn
}
```

