## `main.tf`

```hcl
provider "aws" {
  region = var.primary_region

  default_tags {
    tags = {
      Project     = "stateless-web-application"
      Environment = var.environment
      ManagedBy   = "Terraform"
    }
  }
}

provider "aws" {
  alias  = "replica"
  region = "us-west-2"

  default_tags {
    tags = {
      Project     = "stateless-web-application"
      Environment = var.environment
      ManagedBy   = "Terraform"
    }
  }
}

module "application_data" {
  source = "./modules/application-data"

  providers = {
    aws         = aws
    aws.replica = aws.replica
  }

  name        = "webapp"
  environment = var.environment

  vpc_id                       = var.vpc_id
  database_subnet_ids           = var.database_subnet_ids
  application_security_group_id = var.application_security_group_id

  db_instance_class  = var.db_instance_class
  db_multi_az        = var.db_multi_az
  db_storage_encrypted = true

  db_password         = var.db_password
  db_password_version = var.db_password_version

  oidc_provider_arn         = var.oidc_provider_arn
  oidc_issuer_url           = var.oidc_issuer_url
  service_account_namespace = var.service_account_namespace
  service_account_name      = var.service_account_name

  enable_replication = var.environment == "prod"
}
```

