# Environment variable files

## `dev.tfvars`

```hcl
environment    = "dev"
primary_region = "us-east-1"

vpc_id = "vpc-DEV_REPLACE_ME"

database_subnet_ids = [
  "subnet-DEV_PRIVATE_A",
  "subnet-DEV_PRIVATE_B"
]

application_security_group_id = "sg-DEV_APPLICATION"

db_instance_class = "db.t3.micro"
db_multi_az       = false

oidc_provider_arn = "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/DEV_REPLACE_ME"
oidc_issuer_url   = "https://oidc.eks.us-east-1.amazonaws.com/id/DEV_REPLACE_ME"
```

## `prod.tfvars`

```hcl
environment    = "prod"
primary_region = "us-east-1"

vpc_id = "vpc-PROD_REPLACE_ME"

database_subnet_ids = [
  "subnet-PROD_PRIVATE_A",
  "subnet-PROD_PRIVATE_B"
]

application_security_group_id = "sg-PROD_APPLICATION"

db_instance_class = "db.t3.medium"
db_multi_az       = true

oidc_provider_arn = "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/PROD_REPLACE_ME"
oidc_issuer_url   = "https://oidc.eks.us-east-1.amazonaws.com/id/PROD_REPLACE_ME"
```

Do not put `db_password` in either file. Supply it from a secret manager or environment variable:

```bash
export TF_VAR_db_password="$(secret-tool-or-sops-command)"
```

